// No auth chain elsewhere in this workflow (add-opportunity, delete-
// opportunities etc. are all unauthenticated too) — matching that existing
// convention rather than introducing an inconsistent new pattern here.
const body = $json.body || {};

const name = (body.name || '').toString().trim();
if (!name) {
  throw new Error('"name" is required.');
}

const isDefault = body.is_default === true || body.is_default === 'true';

const stagesInput = Array.isArray(body.stages) ? body.stages : [];
const stages = stagesInput
  .map((s, i) => ({
    name: (s.name || '').toString().trim(),
    win_probability: Number(s.win_probability) || 0,
    display_order: i + 1,
  }))
  .filter((s) => s.name);

if (stages.length === 0) {
  throw new Error('At least one stage is required.');
}

return [{ json: { name, isDefault, stages } }];

// pipelines only has (id, name, is_default) as far as any query in this
// app has ever selected — no confirmed created_by/created_at columns, so
// those aren't written here (add them if your schema actually has them).
const pipelineId = $json.id;
const validated = $('Validate & Build Stages').item.json;
const stages = validated.stages;

const valuesSql = [];
const queryParams = [];
let idx = 1;
for (const s of stages) {
  valuesSql.push(`($${idx}, $${idx + 1}, $${idx + 2}, $${idx + 3})`);
  queryParams.push(pipelineId, s.name, s.win_probability, s.display_order);
  idx += 4;
}

const sqlQuery = `INSERT INTO stages (pipeline_id, name, win_probability, display_order) VALUES ${valuesSql.join(', ')} RETURNING id, pipeline_id, name, win_probability, display_order;`;

return [{
  json: {
    sqlQuery,
    queryParams,
    pipeline_id: pipelineId,
    pipeline_name: validated.name,
    is_default: validated.isDefault,
  },
}];

const stageRows = $input.all().map((item) => item.json);
const meta = $('Build Stage Insert Query').first().json;

return [{
  json: {
    id: meta.pipeline_id,
    name: meta.pipeline_name,
    is_default: meta.is_default,
    stages: stageRows,
  },
}];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();

const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

return [{ json: { requesterId: parseInt(match[1], 10) } }];

const result = $input.first();
if (!result || !result.json || !result.json.id) {
  throw new Error("Deal not found or you do not have permission to edit it.");
}
return [{ json: { success: true, ...result.json } }];

