const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();

const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

return [{ json: { requesterId: parseInt(match[1], 10) } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();

const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

return [{ json: { requesterId: parseInt(match[1], 10) } }];

const requester = $json;
if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (requester.role !== 'admin') throw new Error('Only admins can edit pipelines.');

const body = $('Webhook: update-pipeline').first().json.body || {};
const pipelineId = parseInt(body.id, 10);
if (!Number.isInteger(pipelineId)) throw new Error('"id" must be an integer.');

const name = (body.name || '').toString().trim();
if (!name) throw new Error('"name" is required.');

const isDefault = body.is_default === true || body.is_default === 'true';

return [{ json: { pipelineId, name, isDefault } }];

// Unset Other Pipeline Defaults returns 0 rows on the (common) no-op
// path, which would starve the next node of input — re-emit the
// payload from the actual source of truth so the chain always continues.
return [{ json: $('Check Admin & Payload: update-pipeline').first().json }];

const result = $input.first();
if (!result || !result.json || !result.json.id) {
  throw new Error('Pipeline not found.');
}
return [{ json: { success: true, pipeline: result.json } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();

const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

return [{ json: { requesterId: parseInt(match[1], 10) } }];

const requester = $json;
if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (requester.role !== 'admin') throw new Error('Only admins can delete pipelines.');

const body = $('Webhook: delete-pipeline').first().json.body || {};
const pipelineId = parseInt(body.id, 10);
if (!Number.isInteger(pipelineId)) throw new Error('"id" must be an integer.');

return [{ json: { pipelineId } }];

const counts = $json;
if (Number(counts.pipeline_count) <= 1) {
  throw new Error('Cannot delete the only pipeline.');
}
if (Number(counts.deal_count) > 0) {
  throw new Error(`Cannot delete a pipeline with ${counts.deal_count} deal(s) still in it. Move or delete them first.`);
}
return [{ json: { pipelineId: $('Check Admin & Payload: delete-pipeline').first().json.pipelineId } }];

// Delete Stages can return 0..N rows depending on stage count, which
// would either starve the next node (0 rows) or run it multiple times
// (N rows) — collapse to exactly one item before deleting the pipeline.
return [{ json: { pipelineId: $('Check Delete Safety').first().json.pipelineId } }];

const result = $input.first();
if (!result || !result.json || !result.json.id) {
  throw new Error('Pipeline not found.');
}
return [{ json: { success: true, id: result.json.id } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();

const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

return [{ json: { requesterId: parseInt(match[1], 10) } }];

const requester = $json;
if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (requester.role !== 'admin') throw new Error('Only admins can manage pipeline stages.');

const body = $('Webhook: update-pipeline-stages').first().json.body || {};
const pipelineId = parseInt(body.pipeline_id, 10);
if (!Number.isInteger(pipelineId)) throw new Error('"pipeline_id" must be an integer.');

const stagesInput = Array.isArray(body.stages) ? body.stages : [];
const stages = stagesInput
  .map((s, i) => ({
    id: (s.id === null || s.id === undefined || s.id === '') ? null : parseInt(s.id, 10),
    name: (s.name || '').toString().trim(),
    win_probability: Number(s.win_probability) || 0,
    display_order: i + 1,
  }))
  .filter((s) => s.name);

if (stages.length === 0) throw new Error('At least one stage is required.');

const keepIds = stages.filter((s) => s.id !== null).map((s) => s.id);

return [{ json: { pipelineId, stages, keepIds } }];

// $json here is one row per existing stage (id, name, deal_count) —
// n8n Code nodes default to 'Run Once for All Items', so $input.all()
// gives every row in a single execution.
const existingRows = $input.all().map((item) => item.json);
const ctx = $('Check Admin & Payload: update-pipeline-stages').first().json;
const keepIds = new Set(ctx.keepIds);

const removed = existingRows.filter((r) => !keepIds.has(r.id));
const blocked = removed.find((r) => Number(r.deal_count) > 0);
if (blocked) {
  throw new Error(`Cannot remove stage "${blocked.name}" — it still has ${blocked.deal_count} deal(s). Move or delete them first.`);
}

const removeIds = removed.map((r) => r.id);
return [{ json: { pipelineId: ctx.pipelineId, stages: ctx.stages, removeIds } }];

// Delete Removed Stages can return 0..N rows — collapse to exactly one
// item so the chain always continues regardless of how many stages
// were actually removed (0 is the common case).
return [{ json: $('Check Stage Removal Safety').first().json }];

// Bulk CASE-based update for every stage the client sent an id for —
// keeps existing stage rows (and any deals pointing at them) intact,
// only touching name/win_probability/display_order. A no-op-safe
// SELECT 1 keeps the chain alive when there's nothing to update.
const ctx = $json;
const existing = ctx.stages.filter((s) => s.id !== null);

if (existing.length === 0) {
  return [{ json: { ...ctx, sqlQuery: 'SELECT 1;', queryParams: [] } }];
}

const nameCases = [];
const probCases = [];
const orderCases = [];
const ids = [];
const queryParams = [];
let idx = 1;
for (const s of existing) {
  nameCases.push(`WHEN $${idx} THEN $${idx + 1}`);
  queryParams.push(s.id, s.name);
  idx += 2;
}
for (const s of existing) {
  probCases.push(`WHEN $${idx} THEN $${idx + 1}`);
  queryParams.push(s.id, s.win_probability);
  idx += 2;
}
for (const s of existing) {
  orderCases.push(`WHEN $${idx} THEN $${idx + 1}`);
  queryParams.push(s.id, s.display_order);
  idx += 2;
}
for (const s of existing) {
  ids.push(`$${idx}`);
  queryParams.push(s.id);
  idx += 1;
}

const sqlQuery = `UPDATE stages SET name = CASE id ${nameCases.join(' ')} ELSE name END, win_probability = CASE id ${probCases.join(' ')} ELSE win_probability END, display_order = CASE id ${orderCases.join(' ')} ELSE display_order END WHERE id IN (${ids.join(', ')});`;

return [{ json: { ...ctx, sqlQuery, queryParams } }];

// New stages (no id from the client) get inserted fresh, matching the
// same pattern pipeline-create-new already uses.
const ctx = $json;
const fresh = ctx.stages.filter((s) => s.id === null);

if (fresh.length === 0) {
  return [{ json: { pipelineId: ctx.pipelineId, sqlQuery: 'SELECT 1;', queryParams: [] } }];
}

const valuesSql = [];
const queryParams = [];
let idx = 1;
for (const s of fresh) {
  valuesSql.push(`($${idx}, $${idx + 1}, $${idx + 2}, $${idx + 3})`);
  queryParams.push(ctx.pipelineId, s.name, s.win_probability, s.display_order);
  idx += 4;
}

const sqlQuery = `INSERT INTO stages (pipeline_id, name, win_probability, display_order) VALUES ${valuesSql.join(', ')};`;

return [{ json: { pipelineId: ctx.pipelineId, sqlQuery, queryParams } }];

const requesterId = $('Look Up Requester: update-opportunity').first().json.id;
const before = $('Postgres: Capture Before Stage: update-opportunity').first().json;
const after = $('Postgres: Update Opportunity').first().json;
const oldOwnerId = before ? before.before_assigned_user : null;
const newOwnerId = after.assigned_user;
// Only notify on an actual reassignment to someone else — not a
// no-op resave of the same owner, and not an admin assigning themselves.
const notify = !!newOwnerId && newOwnerId !== oldOwnerId && newOwnerId !== requesterId;
const dmKey = notify ? [requesterId, newOwnerId].sort((a, b) => a - b).join('-') : null;
return [{ json: { notify, dmKey, requesterId, ownerId: newOwnerId, dealId: after.id, pipelineId: after.pipeline_id, dealName: after.name || 'a deal' } }];

